"""Portable PNG playback with one decoded clip at a time; no runtime WebGL/network."""
from pathlib import Path
import json,base64,hashlib,math
from PIL import Image
from concurrent.futures import ProcessPoolExecutor
P=Path(__file__).resolve().parent;original=json.loads((P/'catalog.json').read_text());D={'canvas':original['canvas'],'directions':original['directions'],'actions':{}};assets={}
def pack(job):
 action,view,clip=job;cols=min(8,len(clip['frames']));atlas=Image.new('RGBA',(512*cols,576*math.ceil(len(clip['frames'])/cols)));rects=[]
 for i,f in enumerate(clip['frames']):
  src=P/f['path'];assert hashlib.sha256(src.read_bytes()).hexdigest()==f['sha256'];im=Image.open(src).convert('RGBA');rect=[i%cols*512,i//cols*576,512,576];atlas.paste(im,tuple(rect[:2]));rects.append(rect)
 dest=P/'atlases'/(action+'-'+view+'.webp');dest.parent.mkdir(exist_ok=True);atlas.save(dest,lossless=True,quality=100,method=6,exact=True);decoded=Image.open(dest).convert('RGBA')
 for f,r in zip(clip['frames'],rects):assert decoded.crop((r[0],r[1],r[0]+512,r[1]+576)).tobytes()==Image.open(P/f['path']).convert('RGBA').tobytes(),(action,view,'lossless transport mismatch')
 return {'action':action,'view':view,'path':str(dest.relative_to(P)),'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'rects':rects,'pixels_exact':True,'source_frame_sha256':[f['sha256']for f in clip['frames']]}
jobs=[(a,v,c)for a,d in original['actions'].items()for v,c in d['clips'].items()]
with ProcessPoolExecutor(max_workers=4)as pool:packed=list(pool.map(pack,jobs))
for r in packed:
 action=r['action'];view=r['view'];source=original['actions'][action];c=source['clips'][view];D['actions'].setdefault(action,{'aliases':source['aliases'],'clips':{}})['clips'][view]={'atlas':r['path'],'frames':[{**f,'rect':rect}for f,rect in zip(c['frames'],r['rects'])],'durations_ms':c['durations_ms']};assets[r['path']]='data:image/webp;base64,'+base64.b64encode((P/r['path']).read_bytes()).decode()
(P/'atlas-transport-review.json').write_text(json.dumps({'pass':True,'lossless_exact_rgba':True,'clips':packed,'scope':'Fixed-grid lossless transport only. Every decoded atlas cell is byte-identical to its original RGBA PNG; no scaling or animation fitting.'},indent=2)+'\n')
clock=(P.parents[2]/'tools/sprite-clip-clock.cjs').read_text()
html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Astraeon · ตรวจชุดท่าตัวละคร</title><style>body{font:16px system-ui;background:#20252d;color:#edf1f6;max-width:1080px;margin:24px auto;padding:0 16px}h1{font-size:24px}button,select,input{font:inherit;margin:5px}canvas{display:block;width:min(100%,512px);height:auto;background:repeating-linear-gradient(0deg,#292d34 0 31px,#343942 31px 32px)}p{line-height:1.6}#frame{width:min(380px,80vw)}a{color:#9acfff}#status{min-height:28px}</style><h1>Astraeon · ชุดท่าตัวละคร</h1><p><select id="action" aria-label="ท่า"></select><select id="direction" aria-label="ทิศตัวละคร"></select><label>หมุนกล้อง <select id="camera" aria-label="มุมกล้อง"></select></label></p><canvas id="c" width="512" height="576"></canvas><p><button id="play" disabled>เล่น / หยุด</button><select id="speed" aria-label="ความเร็ว"><option value="1">1×</option><option value="0.25">¼×</option></select><label><input type="checkbox" id="loop" checked>วน</label></p><input type="range" id="frame" min="0" max="0" value="0" disabled aria-label="เฟรม"><p id="status">กำลังโหลด…</p><p>ยืน เดิน และนั่งมีภาพ 8 มุม · ท่าก้มและท่าต่อสู้ใช้ภาพ 4 มุมตามผลวิจัย RO<br>ท่าก้มมี 16 เฟรมต่อมุม · เลื่อนเฟรมหรือเล่นช้าเพื่อตรวจจังหวะ</p><script>__CLOCK__</script><script>
const D=__DATA__,ASSETS=__ASSETS__,names={idle:'ยืน',walk:'เดิน',sit:'นั่ง',pickup:'ก้มเก็บ',ready:'เตรียมสู้',attack1:'หมัดพื้นฐาน',hurt:'โดนโจมตี',dead:'ล้ม',skill:'ใช้สกิล'},$=id=>document.getElementById(id),ctx=$('c').getContext('2d');let clock,atlas=null,current,requested=0,last=null,frameIndex=0;
for(const a of Object.keys(D.actions))$('action').add(new Option(names[a],a));D.directions.forEach((v,i)=>{$('direction').add(new Option(v,i));$('camera').add(new Option(i*45+'°',i))});
function draw(i){if(!current||!atlas)return;frameIndex=i;ctx.clearRect(0,0,512,576);ctx.drawImage(atlas,...current.clip.frames[i].rect,0,0,512,576);$('frame').value=i;$('status').textContent=names[current.action]+' · '+current.logical+' → ภาพ '+current.view+' · เฟรม '+(i+1)+'/'+current.clip.frames.length+' · '+clock.total+' ms'}
async function choose(action=$('action').value,direction=+$('direction').value,camera=+$('camera').value){const token=++requested;clock?.cancel();$('play').disabled=$('frame').disabled=true;$('action').value=action;$('direction').value=direction;$('camera').value=camera;const logical=D.directions[(direction+camera)%8],view=D.actions[action].aliases[logical],clip=D.actions[action].clips[view];try{const next=await new Promise((ok,no)=>{const im=new Image;im.onload=()=>ok(im);im.onerror=()=>no(Error('โหลดภาพไม่ได้'));im.src=ASSETS[clip.atlas]});if(token!==requested)return false;atlas=next;current={action,direction,camera,logical,view,clip};clock=new SpriteClipClock({durations:clip.durations_ms,loop:$('loop').checked});last=null;$('frame').max=clip.frames.length-1;draw(0);$('play').disabled=$('frame').disabled=false;return true}catch(e){if(token===requested){window.LOAD_ERROR=e.message;$('status').textContent=e.message}throw e}}
function select(i){clock.cancel();clock.seek(current.clip.durations_ms.slice(0,i).reduce((a,b)=>a+b,0));draw(i);last=null}
for(const id of ['action','direction','camera'])$(id).onchange=()=>choose();$('frame').oninput=()=>select(+$('frame').value);$('loop').onchange=()=>clock.clip.loop=$('loop').checked;$('play').onclick=()=>{if(clock.running)clock.cancel();else if(clock.finished||clock.time===0)clock.start();else clock.running=true;last=null};
function tick(now){if(clock?.running)draw(clock.advance((last===null?0:Math.max(0,now-last))*+$('speed').value).frame);last=now;requestAnimationFrame(tick)}
window.study={data:D,choose,select,draw,get current(){return current},get clock(){return clock},get frameIndex(){return frameIndex},frame(i){draw(i);return $('c').toDataURL('image/png')}};choose().then(()=>{window.READY=true;requestAnimationFrame(tick)});
</script></html>'''
html=html.replace('__CLOCK__',clock).replace('__DATA__',json.dumps(D,separators=(',',':'))).replace('__ASSETS__',json.dumps(assets,separators=(',',':')));(P/'core-family-review.html').write_text(html);print('Portable reviewer bytes',len(html))
